#!/usr/bin/env python3
"""Independent manuscript and candidate-fact verifier for source-feasibility v27."""
from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path
def sha256(path):
 h=hashlib.sha256()
 with open(path,'rb') as f:
  for b in iter(lambda:f.read(1048576),b''): h.update(b)
 return h.hexdigest()
def main():
 ap=argparse.ArgumentParser()
 for name in ['paper','a7','sync-audit','update-record','production','independent','finalization','output']: ap.add_argument('--'+name,required=True)
 args=ap.parse_args(); paper=Path(args.paper).read_text(); record=json.loads(Path(args.update_record).read_text()); production=json.loads(Path(args.production).read_text()); independent=json.loads(Path(args.independent).read_text()); final=json.loads(Path(args.finalization).read_text()); sync=json.loads(Path(args.sync_audit).read_text()); checks=[]
 def check(name,condition,detail=None): checks.append({'name':name,'pass':bool(condition),'detail':detail})
 def has(label,text): check('paper_fact_'+label,text in paper,text)
 check('paper_hash_record',sha256(args.paper)==record['new_paper_sha256']); check('sync_hash_record',sha256(args.sync_audit)==record['new_sync_audit_sha256']); check('snapshot_paper_hash',sha256(record['snapshot_paper'])==record['old_paper_sha256']); check('snapshot_audit_hash',sha256(record['snapshot_audit'])==record['old_sync_audit_sha256']); check('a7_unchanged',sha256(args.a7)==record['a7_sha256'] and sha256(record['snapshot_a7'])==record['a7_sha256'])
 recovered=paper.replace(record['section']+'\n','',1).replace(record['evidence_anchors'],'',1); check('v26_exactly_recoverable',hashlib.sha256(recovered.encode()).hexdigest()==record['old_paper_sha256']); check('v26_snapshot_byte_exact',recovered==Path(record['snapshot_paper']).read_text()); check('section_present_once',paper.count('### 6.23 Metadata-only recovery of Ribo-seq sources and VeloHARMO release scope')==1); check('previous_section_preserved',paper.count('### 6.22 MAGE nested development CV')==1); check('section_before_discussion',paper.index('### 6.23 Metadata-only recovery')<paper.index('## 7. Discussion'))
 check('production_74_pass',production['overall_pass'] and production['check_counts']=={'total':74,'passed':74,'failed':0}); check('independent_169_pass',independent['independent_pass'] and independent['check_counts']=={'total':169,'passed':169,'failed':0}); check('finalization_47_pass',final['overall_pass'] and final['check_counts']=={'total':47,'passed':47,'failed':0}); check('zero_independent_delta',independent['production_independent_max_numeric_delta']==0); check('bounded_scope_only',final['bounded_source_feasibility_closed'] and not final['utr_cds_mapping_completed'] and not final['raw_read_or_p_site_remapping_completed'] and not final['rk_g1_closed']); check('non_submittable','non-submittable working manuscript' in paper and not record['submittable'] and not sync['last_increment']['submittable']); check('sync_output_hash',sync['output_sha256']==record['new_paper_sha256']); check('sync_scope',sync['rk03_source_feasibility']['status']=='SOURCE_METADATA_RECOVERABLE_REMAP_NOT_PERFORMED' and not sync['rk03_source_feasibility']['raw_remapping_completed'])
 check('sync_increment_hashes',all(sync['last_increment'][k]==record['source_hashes'][source] for k,source in [('protocol_sha256','protocol'),('production_sha256','production'),('independent_sha256','independent'),('finalization_sha256','finalization')]))
 velo=production['veloharmo_organism_feasibility']; by_label={x['label']:x for x in velo}
 for label,x in by_label.items():
  src=x['raw_source']; has(label+'_accession',f"| {label} | {x['organism']} | {x['source_accession']} | {', '.join(src['runinfo_accessions'])} | {src['run_count']} | {src['size_mb']:,} |")
 has('dunn_mapping','Dunn13 to *Drosophila melanogaster* and GSE49197'); has('pop_mapping','Pop14 to *Saccharomyces cerevisiae* and GSE63789')
 velo_runs=sum(x['raw_source']['run_count'] for x in velo); velo_size=sum(x['raw_source']['size_mb'] for x in velo); total_runs=sum(x['run_count'] for x in production['runinfo_evidence'].values()); total_size=sum(x['size_mb'] for x in production['runinfo_evidence'].values())
 has('velo_runs',f'{velo_runs} runs'); has('velo_size',f'{velo_size:,} MB'); has('total_runs',f'{total_runs} runs'); has('total_size',f'{total_size:,} MB'); has('repository_commit','38b48079856aeb9d33a1b10844d77aa8f6640032'); has('tree_blob_counts','14 tree entries and 14 materialized blob files'); has('identical_ecoli_archives','two E. coli matrix archives were byte-identical'); has('ecoli_yeast_checkpoints','E. coli and yeast genetic-algorithm checkpoints were present'); has('four_matrices_absent','No harmonized matrix archive for *P. aeruginosa*, *D. melanogaster*, *S. cerevisiae* or human was present'); has('subtelny_bioproject','Subtelny14/GSE53268 contributed 3 runs and 4,034 MB through its current BioProject relation PRJNA231671'); has('mohammad19','Mohammad19/GSE119104 contributed 10 runs and 5,202 MB'); has('extra_ribo','13 runs and 9,236 MB'); has('no_read_download','did not download FASTQ, BAM or SRA reads'); has('no_utr_or_alignment','did not download FASTQ, BAM or SRA reads, construct UTR–CDS annotations, align reads or fit a model'); has('runinfo_not_download','not data transferred by this audit'); has('raw_not_matrix','a public raw source and a released checkpoint must not be interpreted as a released harmonized matrix'); has('independent_count','169/169 checks'); has('finalization_count','47/47 checks'); has('no_global_offset','no global P-site offset is licensed'); has('reference_freeze','freeze reference versions per study'); has('sample_assignment','assess read length and end assignment per sample'); has('remaining_unperformed','UTR–CDS construction, independent raw-read/P-site remapping, four non-E. coli harmonized matrices, the full natural-distribution report, mechanism validation and model training remain unperformed'); has('rk_g1_open','RK-G1 remains open')
 for label,value in record['source_hashes'].items(): check('evidence_anchor_'+label,f'`{value}`' in paper)
 section=record['section']
 for forbidden in ['UTR–CDS mapping was completed','raw-read remapping was completed','all five harmonized matrices are released','RK-G1 is closed','manuscript is submittable','SOTA']:
  check('forbidden_claim_'+forbidden,forbidden not in section)
 result={'schema':'a8-rk03-source-feasibility-paper-verification-v27','status':'PASS' if all(x['pass'] for x in checks) else 'FAIL','checks':checks,'checks_passed':sum(x['pass'] for x in checks),'checks_total':len(checks),'candidate_facts_passed':sum(x['pass'] for x in checks if x['name'].startswith('paper_fact_')),'candidate_facts_total':sum(x['name'].startswith('paper_fact_') for x in checks),'paper_sha256':sha256(args.paper),'sync_audit_sha256':sha256(args.sync_audit),'v26_recovery_verified':recovered==Path(record['snapshot_paper']).read_text(),'submittable':False}
 Path(args.output).write_text(json.dumps(result,indent=2,sort_keys=True,ensure_ascii=False)+'\n'); print(json.dumps({'status':result['status'],'checks':f"{result['checks_passed']}/{result['checks_total']}",'candidate_facts':f"{result['candidate_facts_passed']}/{result['candidate_facts_total']}",'paper_sha256':result['paper_sha256']},indent=2))
 if result['status']!='PASS': raise SystemExit(1)
if __name__=='__main__': main()
